window.registerChapter({"num": 45, "source_label": "45", "title": "Principles of Drug Use in the Fetus and Neonate", "group": "Neonatal pharmacology", "features": ["Prematurity", "Growth restriction", "Congenital anomaly", "Respiratory distress", "Apnea", "Hypoxemia / cyanosis", "Pulmonary hypertension", "Arrhythmia", "Immune dysfunction", "Jaundice / cholestasis", "Bleeding / thrombosis", "Seizures", "Feeding difficulty", "Glucose disturbance", "Renal dysfunction", "Endocrine disorder", "Eye / hearing", "Bone / joint", "Maternal / placental factors", "Family / comfort"], "pdf_start": 773, "pdf_end": 786, "printed_start": "766", "printed_end": "779", "figures": [{"path": "figures/ch045_p0782_01.jpg", "caption": "• Fig. 45.2 Maturational change in the activity of the cytochrome P450 isoenzymes implicated in human drug metabolism (see text for details).", "caption_matched": true, "pdf_page": 782, "printed_page": "775", "chapter": 45}, {"path": "figures/ch045_p0784_01.jpg", "caption": "• Fig. 45.3 Postnatal changes in the serum half-life of ampicillin. (From Axline SG, Yaffe SJ, Simon HJ. Clinical pharmacology of antimicrobials in premature infants. II. Ampicillin, methicillin, oxacillin, neomycin, and colistin. Pediatrics. 1967;39:97. Copyright American Academy of Pediatrics, 1967.)", "caption_matched": true, "pdf_page": 784, "printed_page": "777", "chapter": 45}, {"path": "figures/ch045_p0780_vector_45_1.jpg", "caption": "• Fig. 45.1 Interrelationships of absorption, distribution, biotransformation, and excretion of a drug and its concentration at the receptor site.", "caption_matched": true, "caption_match_method": "Caption identified in source; vector crop boundaries estimated automatically", "pdf_page": 780, "printed_page": "773", "chapter": 45, "image_type": "vector-diagram render", "bounds_review": "automatic; consult preserved source-page view"}], "tables": [], "cards": 6, "summary": "Small, lipid-soluble, largely unionized and weakly protein-bound. These properties favor movement across placental membranes by passive diffusion.", "pillars": [{"label": "Placental transfer", "text": "Small, lipid-soluble, largely unionized and weakly protein-bound. These properties favor movement across placental membranes by passive diffusion.", "pdf_page": 776, "printed_page": "769"}, {"label": "Body water and distribution", "text": "A larger volume of distribution per kilogram. Newborns have relatively more total and extracellular body water, increasing distribution of hydrophilic drugs.", "pdf_page": 781, "printed_page": "774"}, {"label": "Free drug", "text": "The unbound pharmacologically active fraction. Reduced binding increases the fraction available to exert pharmacologic effects; total adult ranges need cautious interpretation.", "pdf_page": 781, "printed_page": "774"}, {"label": "Enzyme maturation", "text": "Delayed CYP1A2 activity. The primary caffeine demethylation pathway involves CYP1A2, which develops slowly after birth.", "pdf_page": 782, "printed_page": "775"}, {"label": "Renal drug interaction", "text": "Reduced renal perfusion can decrease gentamicin clearance. Prostaglandin inhibition can increase renal vascular resistance and reduce clearance of filtration-dependent drugs.", "pdf_page": 783, "printed_page": "776"}], "reader_html": "<section class=\"source-section\" data-pdf-page=\"773\"><h2>PDF page 773 · Printed 766</h2><h3>Overview</h3><p>45 Principles of Drug Use in the Fetus and Neonate</p><small class=\"source\">PDF p. 773</small><h3>Fetal Drug Disposition</h3><p>The use of medications during pregnancy, prescription and over the counter, is a common and increasing occurrence. Multiple studies have demonstrated that approximately 90% of pregnant women take at least one medication during their pregnancy.1 The average number of medications used during pregnancy has increased by 68%, from 2.5 to 4.2, over the past 30 years, and the use of four or more medications has increased from 23% to 50% of pregnant women.1 When interviewed, patients, physicians, and pharmacists all cite safety of the mother and fetus as a top priority when making decisions about medication use.2 Unfortunately, safety data for the vast majority of medications are limited.</p><small class=\"source\">PDF p. 773</small><p>Most of the drugs administered to the mother reach the fetus; the extent of fetal exposure depends on maternal drug disposition and placental drug transfer. The result of maternal drug disposition is the steady-state concentration of the drug in the maternal circulation, which ultimately determines the amount of the drug available for distribution to the fetal compartment. The steady-state concentration is impacted in varying degrees by maternal absorption, distribution, metabolism, and excretion of drug, all of which are altered during pregnancy.</p><small class=\"source\">PDF p. 773</small><h3>Maternal Pharmacokinetics</h3><p>Drug absorption is affected by a number of factors, including gastric emptying time and intestinal motility, which can significantly change during pregnancy. Gastric emptying time is unchanged in most pregnant women, although intestinal motility is decreased during pregnancy. This results in a reduced rate of absorption of many medications with a potential increase in the extent of absorption because of the prolonged transit time through the intestinal tract. Intestinal metabolizing enzymes are also altered during pregnancy, which can result in either an increase or decrease in drug absorption. Together, these factors impact the oral bioavailability of a drug and ultimately the maternal steady-state concentration.</p><small class=\"source\">PDF p. 773</small><p>Steady-state concentration may also be altered by physiologic changes that occur during pregnancy and that influence drug distribution (Tables 45.1 and 45.2). Maternal total body water, extracellular fluid, and plasma volume all increase gradually during pregnancy by about 32%, 36%, and 50%, respectively (see Table 45.2). Maternal cardiac output also increases by about 40% to 50% as a result of increases in both heart rate and stroke volume. The increase in body water is the primary reason for the observed decreases in peak drug concentrations with standard dosing of water-soluble drugs. When the drug dose is kept constant in the presence of increasing body water, the drug’s apparent volume of distribution (Vd) increases, and steady-state drug concentrations decrease. Such a decrease in steady-state concentrations may alter the therapeutic effect of the drug in the mother and influence the amount of drug available for diffusion across the placenta. Similarly, the increase in cardiac output affects drug transfer by limiting the time a drug resides in the villous space of the placenta and is available for transfer to the fetus.</p><small class=\"source\">PDF p. 773</small><p>Coincident with the changes in body water distribution and cardiac output, the amount of maternal fat increases in a relatively constant proportion to the increase in body weight (see Table 45.2). The result is an increase in Vd for lipophilic drugs and the potential for accumulation within the adipose tissue. Minimal changes in drug efficacy are expected under these circumstances; however, the adipose tissue can act as a reservoir and slowly release the drug into systemic circulation. An increased half-life and prolonged drug effects may be observed.</p><small class=\"source\">PDF p. 773</small><p>Complicating the picture even further is the fluctuation in serum proteins during gestation. Both albumin and α1acid glycoprotein are decreased during pregnancy, resulting in an increase in the free (active) fraction of various highly protein-bound drugs. For example, the free fraction of tacrolimus may increase as much as 91% during mid and late pregnancy.3 This unbound drug is not only the active moiety but also the form that is available for metabolism and elimination by the mother and transfer to the fetus.</p><small class=\"source\">PDF p. 773</small><figure class=\"source-page\"><a href=\"tables/ch045_page0773.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0773.jpg\" alt=\"Original source page 773, including its figures or tables\"></a><figcaption>Original source-page view · PDF 773. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"774\"><h2>PDF page 774 · Printed 767</h2><h3>Maternal Pharmacokinetics</h3><p>Changes in hepatic metabolism during pregnancy affect the normal rate and extent of drug transformation and, ultimately, renal elimination. During pregnancy, hepatic blood flow may increase, leading to increased drug metabolism in the liver; however, this is controversial. Less debated is the alteration in the activity of hepatic enzymes during pregnancy. Enzymes from the cytochrome P450 (CYP) family and those responsible for glucuronidation reactions (uridine 5′-diphosphate glucuronosyltransferase [UGT]) exhibit changes in activity as a result of pregnancy, which can potentially affect maternal and fetal drug exposure (Table 45.3). For example, labetalol is a commonly used antihypertensive agent in pregnant women, and it is extensively metabolized by UGT enzymes that have increased activity during pregnancy. Therefore, as expected, the clearance of labetalol after oral administration is increased during the second and third trimesters by as much as 30%, and the half-life is significantly shorter in the pregnant patient compared with the nonpregnant patient.4 The consequence for the mother is an increase in total daily dose to maintain the same steady-state concentration and well-controlled blood pressure, which is critical for both mother and fetus.</p><small class=\"source\">PDF p. 774</small><p>Alterations in renal elimination during pregnancy also impact mother and fetus. These changes result from the increase in renal blood flow by 10% to 40% and the increase in glomerular filtration rate (GFR) by about 40%.5 As a result, there is enhanced elimination of drugs that are typically excreted unchanged in the urine (e.g., penicillin, digoxin). Active renal transporters (OCT2, P-gp, OAT1) also exhibit increased activity during pregnancy, further enhancing elimination of some medications (metformin, digoxin).6 The net result is a lower steady-state concentration that may or may not be clinically significant for the mother but will likely result in less drug exposure to the fetus.</p><small class=\"source\">PDF p. 774</small><h3>Placental Handling Of Drug</h3><p>In addition to maternal pharmacokinetics, the placenta also plays a major role in determining fetal drug exposure. From the fourth week of gestation until term, the surface area of the placenta increases dramatically to accommodate the increasing needs of the maturing fetus. The surface area of the villi, which represents the real area for exchange, is</p><small class=\"source\">PDF p. 774</small><figure class=\"source-page\"><a href=\"tables/ch045_page0774.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0774.jpg\" alt=\"Original source page 774, including its figures or tables\"></a><figcaption>Original source-page view · PDF 774. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"775\"><h2>PDF page 775 · Printed 768</h2><h3>Placental Handling Of Drug</h3><p>about 3.4 m2 at 28 weeks’ gestation, compared with about 12.6 m2 at term. In contrast, the thickness of the placental membrane decreases with advancing gestation. During late gestation (about 32 weeks), the tissue barrier separating the maternal and fetal circulations may be less than 2 mm, and the areas become specialized in the transport functions of the placenta (i.e., rapid diffusion of substances) rather than the metabolic ones. By term, the placenta has only a single cell layer of fetal chorionic tissue separating the fetal capillary endothelium from the maternal blood. This separation, with its loose intercellular connections, presents little hindrance to small molecule transfer. Both the decreasing membrane thickness and increasing surface area with advancing gestation favor the greater transfer of drugs as gestation progresses.</p><small class=\"source\">PDF p. 775</small><p>Very little specific information defines the mechanisms of the processes and extent of drug transfer across the placenta. A number of interdependent variables influence the rate and extent of drug transfer across the placenta from the maternal to the fetal compartment. Most investigators and clinicians believe that the vast majority of compounds found in the maternal circulation will cross the placenta and enter the fetal compartment. Therefore the fundamental questions are about the rate and extent of this activity. Unfortunately, even today, this information is only partially available for just a few chemical entities. Similarly, the mechanisms by which drugs are transferred across the placenta are not always clear, and more than one type of transfer may be involved.</p><small class=\"source\">PDF p. 775</small><p>The possible modes of drug transfer across the placenta are listed in order of importance in Box 45.1. For most drugs and other compounds, it is presumed that the primary mode of transfer is by simple, passive, nonionic diffusion, which requires no energy. Pinocytosis and phagocytosis require energy and likely occur much too slowly to have any</p><small class=\"source\">PDF p. 775</small><p>significant impact on drug transfer, whereas facilitated and active transport play a role for some drugs.</p><small class=\"source\">PDF p. 775</small><p>Corticosteroids are an example of a drug class that undergoes facilitated diffusion. No energy is required to transfer steroids across the placenta, but the steroid must form a complex with a specific carrier on the placenta to be transferred from maternal to fetal circulation. Active transport occurs in a similar way, but energy is required for active transport to take place. Metformin is thought to undergo active transport via the placental OCT3 transporter, resulting in fetal concentrations that are 70% to greater than 100% of maternal concentrations.6,8 Another important aspect of active transport involves the efflux of drugs back into maternal circulation subsequent to binding with a carrier on the placenta. Digoxin is one such drug that binds to the carrier protein P-gp.6 P-gp is expressed on the maternal side of the placental-trophoblastic layer, where it mediates active efflux from the fetal compartment. This efflux is unidirectional from the fetal to maternal circulation and is probably responsible for the removal of a number of highly lipid-soluble compounds and drugs from the fetal compartment. P-gp expression is highest during the first trimester and declines over the course of the pregnancy, potentially protecting the developing fetus during its most vulnerable stages.9</p><small class=\"source\">PDF p. 775</small><figure class=\"source-page\"><a href=\"tables/ch045_page0775.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0775.jpg\" alt=\"Original source page 775, including its figures or tables\"></a><figcaption>Original source-page view · PDF 775. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"776\"><h2>PDF page 776 · Printed 769</h2><h3>Placental Handling Of Drug</h3><p>As stated, most drugs are transported across the placenta by simple diffusion, and the factors that influence this process have been more extensively evaluated than those affecting the other transport mechanisms discussed. Simple diffusion is described by the Fick equation as follows:</p><small class=\"source\">PDF p. 776</small><p>Rate of diffusion = K A (Cm−Cf) /d</p><small class=\"source\">PDF p. 776</small><p>where K is the diffusion constant of the drug, which is dependent on the drug’s physicochemical characteristics; A is the surface area of the membrane to be traversed; Cm and Cf are the concentrations of the drug in maternal and fetal blood, respectively; and d is the thickness of the membrane to be traversed. Thus Cm − Cf represents the concentration gradient across the placenta, which is primarily regulated by the surface area (A) and thickness (d) of the placenta. As previously mentioned, changes in these characteristics as pregnancy progresses allow for easier transfer of drugs from maternal to fetal circulation.</p><small class=\"source\">PDF p. 776</small><p>The important physicochemical characteristics that influence passive drug transfer across membranes (i.e., placenta), as represented by K in the Fick equation, are outlined in Box 45.2. The characteristics that facilitate placental transfer include high lipid solubility, the unionized form under physiologic and pathophysiologic conditions, low molecular weight (&lt;500 daltons), and low protein binding. Very few clinically important drugs meet all these “ideal” characteristics, which explains the high degree of variability reported in various studies of placental transfer. There are also a very limited number of medications, like heparin and insulin (molecular weights &gt;1000 daltons), with any one characteristic that renders the drug 100% impermeable.</p><small class=\"source\">PDF p. 776</small><p>Other factors important to drug transfer across the placenta include differences between the maternal and fetal osmotic pressures and pH, as well as changes in uterine or placental blood flow. Under normal circumstances, the maternal osmotic pressure is higher than that in the fetal</p><small class=\"source\">PDF p. 776</small><p>compartment, and a pH difference of 0.1 to 0.15 unit exists between the fetal and maternal blood (i.e., fetal umbilical blood is −0.1 unit of pH lower than maternal blood). If alterations in either the osmotic pressures or pH occur, drug transfer will be affected. With regard to changes in blood flow, the placental flow increases from 50 mL/min at 10 weeks to 600 mL/min at term, whereas uterine blood flow approaches 150 mL/kg/min of newborn body weight at term.10 Depending on the physicochemical characteristics of the drug, blood flow may have an important influence on the rate and amount of drug transfer.</p><small class=\"source\">PDF p. 776</small><p>The degree to which the placenta metabolizes a drug, if at all, also influences the amount that is estimated to cross the placenta and the amount of active drug that reaches the fetus. Many CYP mixed-function oxidase enzymes have been isolated from the human placenta.11 The placenta also possesses some capacity to catalyze phase II conjugation reactions, which enhance the water solubility of the affected drugs and ultimately drug transfer.</p><small class=\"source\">PDF p. 776</small><p>The number of different substrates biotransformed by enzymes located in the placenta is large, but the actual content of CYP enzymes in placental tissue is low, and the activity appears to be much lower than that determined in the fetal or adult liver. Thus the actual contribution of placental enzyme activity to the biotransformation of administered drugs is believed to be inconsequential and of limited clinical significance for most drugs administered maternally. Nevertheless, the differential placental metabolism of certain corticosteroids (e.g., prednisolone, in contrast to betamethasone)12 and the resulting poor clinical outcomes with prednisolone compared with betamethasone in enhancing fetal lung maturation suggest a significant effect of placental metabolism in certain clinical scenarios.</p><small class=\"source\">PDF p. 776</small><h3>Fetal Pharmacokinetics</h3><p>Contrary to the popular belief that the fetus resides in a privileged and protected environment, it is clear that it is exposed to virtually every chemical entity to which the mother is exposed. Thus the absorption of most drugs into the fetal circulation is both rapid and complete. Most of this absorption is believed to occur through passive nonionic diffusion down the concentration gradients between maternal and fetal blood (which oppose each other in the placental villi), where they are separated by only a single layer of cells. However, as described earlier, a number of energy-dependent placental transporters have been characterized and are responsible for drug influx and efflux.11 In addition, the fetus may undergo continued drug exposure after its elimination because of the recirculation of amniotic fluid through the fetal gastrointestinal tract.</p><small class=\"source\">PDF p. 776</small><p>Investigators have recently taken the first steps in the development of a fetal pharmacokinetic model that could be used to predict fetal drug exposure and toxicity in the future.13 Although this model is still under development and validation, we continue to have little knowledge of a drug’s fate or potential activity once it is within fetal</p><small class=\"source\">PDF p. 776</small></section><section class=\"source-section\" data-pdf-page=\"777\"><h2>PDF page 777 · Printed 770</h2><h3>Fetal Pharmacokinetics</h3><p>circulation. It will likely be distributed to the fetal organs in a manner similar to that observed after birth. However, it is not known whether there are any unusual fetal barriers to drug distribution analogous to those of the blood–brain barrier or the anterior chamber of the eye. In fact, it is not even known whether these barriers actually exist during fetal life. Additionally, a drug may have an increased affinity for a specific fetal tissue that is not the typical target tissue. For example, tetracycline has a high affinity for fetal teeth and warfarin for fetal bones.14 Protein binding will also affect drug distribution. The fetus has lower levels of serum proteins, and the proteins that are present have a lower affinity for binding drugs. The serum protein levels increase with gestational age, but free drug levels remain high secondary to the binding affinity of fetal proteins.</p><small class=\"source\">PDF p. 777</small><p>Once a drug has reached various organs, it is often not known whether it has any effect at all. It is clear that both receptor number and receptor affinity change during development. Likewise, receptor–effector coupling undergoes a programmed maturation. Thus, even though a drug may interact with specific receptors, there may be no discernible pharmacologic effect because the effector mechanisms have not yet been developed.</p><small class=\"source\">PDF p. 777</small><p>There is no question that the mean residence time for drugs in the fetus is longer than that observed in older children and adults because of the immaturity of drug clearance mechanisms. For drugs undergoing significant hepatic metabolism, there are many unknown factors. Although most hepatic metabolic pathways are less active in the fetus than in adults, this is not universally true. Moreover, in the fetus, the adrenal gland has a significant complement of drug-metabolizing enzymes that, although active during fetal and neonatal life, disappear by 6 months of postnatal age. Thus the true ability of the fetus to metabolize drugs is largely unknown, but it at least partially depends on the particular drug under consideration, the gestational age of the fetus, and its drug metabolism phenotype.</p><small class=\"source\">PDF p. 777</small><p>As noted, multiple enzyme systems are involved in xenobiotic metabolism within the body. Of the phase I or oxidative enzymes, CYP predominates. The human fetal liver contains many different CYP forms (Table 45.4), although they are present in fewer numbers and with less density than in the adult liver. The liver of the human fetus does exhibit</p><small class=\"source\">PDF p. 777</small><p>some CYP450 activity, but the overall functional capacity of fetal CYP activity is very low, and its metabolic capacity is qualitatively and quantitatively very different from the activity observed in the adult liver. For example, nevirapine is metabolized by the adult liver via CYP 3A4, 2B6, and 2D6 but in the fetus only negligible metabolism of the drug occurs, and it does not impact overall fetal drug exposure.15</p><small class=\"source\">PDF p. 777</small><p>The enzyme activity observed in the fetus is primarily caused by CYP3A7 expression, which is minimally expressed in the adult liver. CYP3A7 may serve as a detoxifying enzyme and protect the fetus from steroids and retinoic acid derivatives. Other enzymes expressed also serve protective roles for the fetus, such as CYP2E1, which is involved in fetal alcohol metabolism.14 Although our understanding of the expression of CYP forms by the fetus is growing exponentially, the extent of our understanding of their function remains limited. Nevertheless, the available data clearly indicate that the overall functional capacity of the fetal liver to effectively metabolize xenobiotics is far less than that of the adult liver.16</p><small class=\"source\">PDF p. 777</small><p>Even more limited is the ability of the fetus to clear drugs that are entirely eliminated by renal excretion. The ontogeny of glomerular filtration and tubular secretion has been well studied, and renal elimination is not a significant mechanism of drug excretion for the fetus. Furthermore, any drug that is renally excreted by the fetus is eliminated into the amniotic fluid, which the fetus may swallow, leading to redistribution of the drug and the need for elimination again.</p><small class=\"source\">PDF p. 777</small><h3>Exposure Of The Fetus To Drugs</h3><p>As discussed, most of the pharmacologic agents present in the maternal circulation cross the placenta and enter the fetal circulation and are therefore potentially harmful to the fetus. The adverse effects of in utero exposure to drugs can vary from reversible effects such as altered thyroid or renal function to irreversible effects such as fetal death, intrauterine growth restriction, structural malformations, and mental retardation.17,18 Unfortunately, the details of drug interaction with the maternal-placental-fetal unit for most drugs are extremely complex and not well studied. In a review of 172 medications approved by the US Food and Drug Administration (FDA) from 2000 to 2010, the teratogenic risk was undetermined for 97.7% of the medications.7 This lack of knowledge not only places the fetus at risk but may also cause prescribers to inadequately treat pregnant women for fear of a drug’s teratogenic potential.1</p><small class=\"source\">PDF p. 777</small><p>A number of drugs are possible teratogens in humans; however, at present only a few (&lt;30) have been positively identified as such.14 Preclinical testing during drug development is typically performed using a rodent model; however, not all human teratogens are teratogens in different animal species, and further postmarketing phase IV epidemiologic evaluations for teratogenic effects are vitally important. It has been estimated that to establish that a given drug changes the naturally occurring frequency of a congenital</p><small class=\"source\">PDF p. 777</small><figure class=\"source-page\"><a href=\"tables/ch045_page0777.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0777.jpg\" alt=\"Original source page 777, including its figures or tables\"></a><figcaption>Original source-page view · PDF 777. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"778\"><h2>PDF page 778 · Printed 771</h2><h3>Exposure Of The Fetus To Drugs</h3><p>deformity by 1%, a sequential trial involving about 35,000 patients would be required. In the case of abnormalities that occur quite often in the population, physicians may not be alerted to the direct causal relationship between exposure of the fetus to the drug and the resulting adverse effect. Therefore, for most medications, it remains virtually impossible to prove teratogenicity, and prescribers must often rely on international pregnancy drug registries, the experience and reports of others, or animal studies to guide drug therapy during pregnancy.</p><small class=\"source\">PDF p. 778</small><p>The teratogenic effects of thalidomide, discovered in the 1960s, illustrate the totally unpredictable nature of drug toxicity in the fetus during the first trimester. Thalidomide doses that induced analgesia with no demonstrable undesirable side effects in the mother produced major structural defects in the fetus.19 The discovery that thalidomide caused congenital malformations was made possible because this drug was widely used, induced dramatic and rare congenital defects, and had a high probability (estimated at 20%–35%) of producing a teratogenic effect after exposure from the third to the eighth week after conception. Unfortunately, these three criteria are rarely met when one is attempting to assess the teratogenicity of other drugs.</p><small class=\"source\">PDF p. 778</small><p>In the absence of any clear data for a particular drug’s teratogenic potential, other factors can be taken into consideration to help predict the risk of drug exposure to the fetus. The timing of drug exposure is frequently a critical determinant of the effect of a drug on the fetus. During the first week of gestation, the most common adverse effect of drugs is the termination of pregnancy, which may occur before the woman even knows that she is pregnant. Exposure of the preimplantation embryo to embryotoxic drugs may retard development, perhaps by decreasing cell numbers in the blastocyst, or it may even produce malformations. In the second to the eighth week of gestation, drugs may produce dramatic and catastrophic structural malformations, such as the neural tube defects associated with valproic acid and carbamazepine. Other adverse effects during this period of organogenesis may include fetal waste, transplacental carcinogenesis (diethylstilbestrol), and intrauterine growth restriction. From the third to the ninth month of gestation, the effects of drugs on a fetus are widely varied and relatively specific to the drug administered. For example, angiotensin-converting enzyme (ACE) inhibitors and angiotensin II receptor blockers (ARBs) may cause oligohydramnios, tetracycline is associated with staining of the teeth and bones, and paroxetine may slightly increase the risk for cardiac malformations.17</p><small class=\"source\">PDF p. 778</small><p>In addition to the drug itself and timing of administration, the drug dose, maternal disease state, and number of medications administered are also important factors impacting teratogenicity. Epilepsy is one disease state in which these factors must be considered. Many antiepileptic drugs (AEDs) are associated with an increased risk of congenital malformations as well as adverse cognitive outcomes of the child. However, uncontrolled epilepsy can also be harmful to the fetus. Prolonged seizures have been</p><small class=\"source\">PDF p. 778</small><p>associated with fetal loss, and frequent tonic-clonic seizures are associated with poorer cognitive development of the child.20 It has been suggested that the teratogenic effects of AEDs are more common in women on multiple anticonvulsant medications and those on higher doses.20 For these reasons, it is ideal to optimize an epileptic woman’s drug regimen before conception with the fewest drugs possible at the lowest effective doses. According to the FDA and the American Epilepsy Society, valproate should specifically be avoided as part of this optimization unless other treatments have failed.21 Frequent monitoring throughout pregnancy is also required, as the state of pregnancy can significantly impact the pharmacokinetics of AEDs, possibly impacting both seizure control and fetal well-being.</p><small class=\"source\">PDF p. 778</small><p>The decision of whether to give a drug during pregnancy is difficult. If a mother is not healthy, the baby may not be healthy. If drug therapy can improve the mother’s health, it seems it should also benefit the fetus. However, limited or incomplete knowledge of fetal outcomes for most drugs complicates the picture. Available information on the potential adverse effects for some of the commonly prescribed known or suspected teratogens is listed in Table 45.5.17</p><small class=\"source\">PDF p. 778</small><h3>Neonatal Drug Disposition</h3><p>At birth, a term infant in North America typically receives three medications: an ophthalmic antimicrobial agent, vitamin K, and the hepatitis B vaccine. Sick and premature infants receive an increasing number of drugs, with the constant introduction of new drugs or old drugs with new indications into the neonatal therapeutic armamentarium. The appropriate and safe use of these drugs requires a thorough understanding of their various pharmacologic profiles. Fig. 45.1 illustrates many of the interrelationships of the absorption, distribution, binding, biotransformation, and excretion of a drug and its concentration at the locus of action.22 To produce its characteristic effect, a drug must be present in sufficient concentrations at its sites of action or receptor sites. The concentration of the drug at the receptor site depends not only on the amount of drug administered but also on the interrelationships listed in the preceding and shown in Fig. 45.1. Those factors that have been evaluated in the newborn infant differ substantially from those in the adult and even in the young infant beyond the neonatal period.22</p><small class=\"source\">PDF p. 778</small><h3>Absorption Of Drugs In The Neonate</h3><p>Drug absorption is the passage of a drug from its site of administration into the circulation. In neonates who can tolerate gastric feedings, the oral route of drug administration is the most common because of its convenience and safety. The absorption of a drug or substance through the gastrointestinal system may be defined as the net movement of a drug from the gastrointestinal lumen into the systemic circulation draining this organ. This process entails the movement of drugs across the gastrointestinal epithelium,</p><small class=\"source\">PDF p. 778</small><figure class=\"source-page\"><a href=\"tables/ch045_page0778.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0778.jpg\" alt=\"Original source page 778, including its figures or tables\"></a><figcaption>Original source-page view · PDF 778. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"779\"><h2>PDF page 779 · Printed 772</h2><h3>Absorption Of Drugs In The Neonate</h3><p>TABLE</p><small class=\"source\">PDF p. 779</small><h3>Selected Therapeutic Agents With Known Or Suspected Teratogenic Potential</h3><p>45.5</p><small class=\"source\">PDF p. 779</small><p>Drug Potential Defect(s) and Adverse Effects</p><small class=\"source\">PDF p. 779</small><p>Angiotensin-converting</p><small class=\"source\">PDF p. 779</small><p>Skull ossification defects, oligohydramnios, fetal</p><small class=\"source\">PDF p. 779</small><p>enzyme (ACE) inhibitors, angiotensin II receptor blockers (ARBs)</p><small class=\"source\">PDF p. 779</small><p>lung hypoplasia, renal failure</p><small class=\"source\">PDF p. 779</small><p>Carbamazepine Neural tube defects, craniofacial defects,</p><small class=\"source\">PDF p. 779</small><p>developmental delay</p><small class=\"source\">PDF p. 779</small><p>Fluconazole Abnormal facies, limb defects, cleft palate,</p><small class=\"source\">PDF p. 779</small><p>congenital heart defects</p><small class=\"source\">PDF p. 779</small><p>Isotretinoin Hydrocephalus, central nervous system</p><small class=\"source\">PDF p. 779</small><p>defects, small/absent ears, hearing or eyesight problems, small or missing thymus, micrognathia, spontaneous abortion, stillbirth, developmental delay, congenital heart defects</p><small class=\"source\">PDF p. 779</small><p>Lithium Ebstein anomaly, altered thyroid function, cardiac</p><small class=\"source\">PDF p. 779</small><p>arrhythmias, hypoglycemia, polyhydramnios</p><small class=\"source\">PDF p. 779</small><p>Methimazole Esophageal atresia, choanal atresia,</p><small class=\"source\">PDF p. 779</small><p>hypothyroidism, goiter, aplasia cutis</p><small class=\"source\">PDF p. 779</small><p>Methotrexate Spontaneous abortion, craniofacial/skull</p><small class=\"source\">PDF p. 779</small><p>abnormalities, limb defects, developmental delay</p><small class=\"source\">PDF p. 779</small><p>Misoprostol Skull defects, cranial nerve palsies, facial</p><small class=\"source\">PDF p. 779</small><p>malformations, limb defects, spontaneous abortion</p><small class=\"source\">PDF p. 779</small><p>Mycophenolate mofetil Ear abnormalities; cleft lip and palate; anomalies of</p><small class=\"source\">PDF p. 779</small><p>the distal limbs, heart, esophagus, and kidney; spontaneous abortion</p><small class=\"source\">PDF p. 779</small><p>Paroxetine Cardiac malformations, respiratory distress,</p><small class=\"source\">PDF p. 779</small><p>persistent pulmonary hypertension of the newborn</p><small class=\"source\">PDF p. 779</small><p>Phenytoin Fetal hydantoin syndrome with mild to moderate</p><small class=\"source\">PDF p. 779</small><p>growth and mental deficiencies, limb anomalies, and dysmorphic facies (low nasal bridge, short nose, eyelid ptosis), vitamin K deficiency with resultant hemorrhage</p><small class=\"source\">PDF p. 779</small><p>Tetracyclines (doxycycline,</p><small class=\"source\">PDF p. 779</small><p>Discoloration of fetal teeth, inhibition of bone</p><small class=\"source\">PDF p. 779</small><p>minocycline, tetracycline)</p><small class=\"source\">PDF p. 779</small><p>elongation/growth</p><small class=\"source\">PDF p. 779</small><p>Thalidomide Limb reduction defects, limb hypoplasia, ear</p><small class=\"source\">PDF p. 779</small><p>and eye abnormalities, cardiac defects, developmental delay</p><small class=\"source\">PDF p. 779</small><p>Valproic acid Neural tube defects, cardiac defects,</p><small class=\"source\">PDF p. 779</small><p>developmental delay, autism</p><small class=\"source\">PDF p. 779</small><p>Warfarin Nasal hypoplasia, stippled epiphyses,</p><small class=\"source\">PDF p. 779</small><p>developmental delay, spontaneous abortion, fetal hemorrhage, fetal death</p><small class=\"source\">PDF p. 779</small><p>Additional Information</p><small class=\"source\">PDF p. 779</small><p>Critical time period is ≥14 weeks’ gestation;</p><small class=\"source\">PDF p. 779</small><p>no proven risk of defect with first trimester use</p><small class=\"source\">PDF p. 779</small><p>Critical time period is first trimester</p><small class=\"source\">PDF p. 779</small><p>Greatest impact at doses &gt;400 mg/day for</p><small class=\"source\">PDF p. 779</small><p>multiple weeks during the first trimester</p><small class=\"source\">PDF p. 779</small><p>Risk of major malformation is 15% and may</p><small class=\"source\">PDF p. 779</small><p>occur with any dose or duration</p><small class=\"source\">PDF p. 779</small><p>Critical time period is ≤8 weeks’ gestation</p><small class=\"source\">PDF p. 779</small><p>for Ebstein anomaly; other adverse events are rare and associated with use later in pregnancy and higher doses</p><small class=\"source\">PDF p. 779</small><p>Critical time period is first trimester for impact</p><small class=\"source\">PDF p. 779</small><p>on thyroid; other defects are rare</p><small class=\"source\">PDF p. 779</small><p>Critical time period is 6–8 weeks’ gestation;</p><small class=\"source\">PDF p. 779</small><p>greatest impact at doses &gt;10 mg/week</p><small class=\"source\">PDF p. 779</small><p>Use in third trimester can increase the risk of</p><small class=\"source\">PDF p. 779</small><p>uterine rupture</p><small class=\"source\">PDF p. 779</small><p>Critical time period is first trimester; 25% risk</p><small class=\"source\">PDF p. 779</small><p>of congenital malformation; 45%–49% of first trimester exposures result in fetal loss</p><small class=\"source\">PDF p. 779</small><p>Other selective serotonin reuptake inhibitors</p><small class=\"source\">PDF p. 779</small><p>associated with respiratory distress and pulmonary hypertension, but less risk of cardiac defects</p><small class=\"source\">PDF p. 779</small><p>Critical time period is 3–12 weeks’ gestation</p><small class=\"source\">PDF p. 779</small><p>for hydantoin syndrome; at least one feature of syndrome present in 40% of exposed neonates Critical time period for hemorrhagic disease is</p><small class=\"source\">PDF p. 779</small><p>≥13 weeks’ gestation; prevent with vitamin K administration to mother and baby</p><small class=\"source\">PDF p. 779</small><p>Critical time period is ≥12 weeks’ gestation</p><small class=\"source\">PDF p. 779</small><p>Critical time period is 3–8 weeks’ gestation;</p><small class=\"source\">PDF p. 779</small><p>defects can occur following just one dose</p><small class=\"source\">PDF p. 779</small><p>Critical time period is first trimester for nasal</p><small class=\"source\">PDF p. 779</small><p>hypoplasia and stippled epiphyses; other adverse effects may occur from exposure at any time during pregnancy</p><small class=\"source\">PDF p. 779</small><figure class=\"source-page\"><a href=\"tables/ch045_page0779.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0779.jpg\" alt=\"Original source page 779, including its figures or tables\"></a><figcaption>Original source-page view · PDF 779. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"780\"><h2>PDF page 780 · Printed 773</h2><h3>Selected Therapeutic Agents With Known Or Suspected Teratogenic Potential</h3><p>which behaves like a semipermeable lipid membrane and constitutes the main barrier to absorption. The various processes operating to induce the transepithelial membrane movement of drug molecules include simple diffusion through lipid membranes or aqueous pores of the membrane; filtration through aqueous channels or membrane pores; carrier-mediated transport, such as active transport or facilitated diffusion; and vesicular transport, such as pinocytosis. Of these, the most important is the process of simple diffusion because most drugs administered orally are absorbed through this process.</p><small class=\"source\">PDF p. 780</small><p>The rate and extent of gastrointestinal drug absorption are partly determined by the physical and chemical characteristics of the drug. Polarity, nonlipid solubility, and a large molecular size tend to decrease absorption. In contrast, nonpolarity, lipid solubility, and a small molecular size increase absorption. The degree of ionization, determined by the pKa of the drug and the pH of the solution in which it exists, is an important determinant in drug absorption. The gastrointestinal epithelium is more permeable to the nonionized form because this portion is usually lipid soluble and favors absorption. The degree of drug ionization changes as the pH increases from the stomach through the distal portion of the gut.</p><small class=\"source\">PDF p. 780</small><p>Ionization also changes with the substantial changes in gastric pH observed during the neonatal period. Gastric acid production is generally low at birth, and the gastric pH is usually 6 to 8. In the first few hours of life, a burst of acid secretion occurs, decreasing the pH to values of 1 to 3.</p><small class=\"source\">PDF p. 780</small><p>Acid secretion then returns to a low level, and the gastric pH remains near neutral for the first 10 days of life.23 The gastric pH then tends to fall and approaches adult values by 2 years of age. Clinically, the result of any decrease in pH is the increased absorption of weak acids (e.g., furosemide, phenobarbital) because they are more likely to be in the unionized, lipid-soluble state. Conversely, an increase in pH enhances the absorption of weak bases (e.g., morphine, erythromycin) and limits the absorption of weak acids. Thus a neonate transitioning from intravenous to enteral morphine may not require the standard threefold increase in dose used in older children. Instead, the administration of an oral dose that is two times that of the intravenous dose is typically sufficient.</p><small class=\"source\">PDF p. 780</small><p>The slow gastric emptying time and intestinal motility in the newborn may also affect drug absorption. The primary site for drug absorption is the proximal bowel, which has the greatest absorptive surface area. With slower motility and emptying, it takes longer for a drug to reach this site of absorption, and the rate at which absorption can occur may be limited. Conversely, a slow transit time or slow intestinal motility may facilitate the absorption of some drugs, such as iron, which is primarily absorbed in the duodenum.</p><small class=\"source\">PDF p. 780</small><p>The colonization of the gastrointestinal tract by bacteria is another process that influences intestinal drug absorption. Intestinal flora are involved in the metabolism of bile salts and selected drugs, as well as intestinal motility. The gut flora vary with age, type of drug delivery, and type of feeding. Concurrent drug therapy also plays a role, particularly</p><small class=\"source\">PDF p. 780</small><figure class=\"source-page\"><a href=\"tables/ch045_page0780.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0780.jpg\" alt=\"Original source page 780, including its figures or tables\"></a><figcaption>Original source-page view · PDF 780. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"781\"><h2>PDF page 781 · Printed 774</h2><h3>Selected Therapeutic Agents With Known Or Suspected Teratogenic Potential</h3><p>because antibiotics, which decrease intestinal flora, are some of the most commonly administered medications to neonates. Although the actual characterization of the colonization of intestinal flora relative to age is limited, data suggest that all full-term, formula-fed, vaginally delivered infants are colonized with anaerobic bacteria by 4 to 6 days of postnatal life. By 5 to 12 months of age, an adult pattern of microbial reduction products appears to be established.</p><small class=\"source\">PDF p. 781</small><p>Additional factors such as pancreatic and biliary function and the activity of intestinal drug-metabolizing enzymes and efflux transports can also alter absorption. As expected, this function and activity are not fully developed in the neonate, further contributing to the differences in absorption observed between neonates and older children or adults.23</p><small class=\"source\">PDF p. 781</small><p>Overall, the differences in the neonatal gastrointestinal tract likely impact the rate of drug absorption but not the extent. The gastrointestinal absorption of drugs is relatively slow in the neonate, which can prolong the time to reach the steady-state concentration but not the actual concentration achieved. Thus the clinical significance of altered absorption in the neonate is likely minor for the majority of medications.</p><small class=\"source\">PDF p. 781</small><h3>Drug Distribution In The Neonate</h3><p>Distribution of a drug into the extravascular tissues is largely influenced by body composition, which is much different in a neonate compared with an older infant or adult. Total body water is about 80% of body weight in a term infant and is an even greater percentage of body weight in preterm neonates. In comparison, an adult has a total body water percentage of approximately 60%.24 The extracellular water compartment of a neonate is also larger, whereas the fat content is lower. At 28 weeks’ gestation, body fat is only 1% to 3% of body weight, and at term, it is 15% to 28%.14 In addition, the fat that is found in neonates is about 50% water, compared with 25% water in an adult. The end result of these differences is a larger Vd for hydrophilic drugs, whereas lipophilic drugs may not distribute as extensively as expected. In the case of water-soluble medications, a lower peak serum concentration, higher milligram-per-kilogram doses, and delayed excretion are often observed. For example, the Vd for acyclovir in neonates has been reported to be as high as 10.8 L/kg, compared with 0.7 L/kg in adults. To achieve therapeutic concentrations of acyclovir in term neonates, a dose of 20 mg/kg every 6 hours is required, compared with 10 mg/kg every 8 hours in older children and adults.25</p><small class=\"source\">PDF p. 781</small><p>Protein binding also plays an important role in neonatal drug distribution. The unbound or free concentration of a drug in plasma is considered to be the pharmacologically active fraction of the drug. For some drugs, the binding to plasma proteins is decreased in the newborn compared with that in the adult (Table 45.6).23 Reasons for this deficiency include decreased albumin concentrations in the neonate as well as qualitative differences in neonatal albumin. Albumin is the primary drug-binding protein in both neonates and</p><small class=\"source\">PDF p. 781</small><p>adults, but the albumin found in neonates has less affinity for drugs compared with adult albumin. Competitive binding to albumin by many endogenous substrates, such as hormones, may also decrease protein binding. Hyperbilirubinemia may accentuate this competition because bilirubin is able to displace some drugs, such as phenytoin, from the albumin-binding site. This activity contrasts with the well-known drug–protein binding interaction with bilirubin, in which drugs such as sulfonamides or their excipients may displace bilirubin from its binding site. Regardless of cause, the decrease in protein binding observed in neonates leads to an increase in free or active drug. This outcome suggests that a more intense pharmacologic response may be obtained in the newborn infant than the adult for the same total drug concentration. Clinically, decreased protein binding in the neonate does not typically affect initial dosing, but it is important to consider this factor in the application of adult therapeutic plasma concentrations to the neonatal patient.</p><small class=\"source\">PDF p. 781</small><h3>Drug Metabolism In The Neonate</h3><p>Many drugs are lipophilic and require conversion to more water-soluble metabolites for efficient elimination from the body. These metabolic processes most often occur via drug uptake into the liver and are traditionally categorized as either phase I or II reactions. In a phase I reaction, a more polar compound is formed through oxidation, reduction, or hydrolysis of the parent molecule. Phase II metabolism involves conjugation with endogenous substrates such as sulfate, acetate, and glucuronic acid. Drugs may be conjugated directly or made more amenable to conjugation after the introduction of a functional group by phase I metabolism (e.g., hydroxylation). Typically, the metabolites formed by either type of reaction are inactive; however, some drugs can be transformed into active metabolites (e.g., theophylline to caffeine). It is well recognized that the neonate may have limited uptake of drugs into the liver and is deficient in many of the enzymes responsible for phases I and II drug metabolism.22,23</p><small class=\"source\">PDF p. 781</small><figure class=\"source-page\"><a href=\"tables/ch045_page0781.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0781.jpg\" alt=\"Original source page 781, including its figures or tables\"></a><figcaption>Original source-page view · PDF 781. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"782\"><h2>PDF page 782 · Printed 775</h2><h3>Drug Metabolism In The Neonate</h3><p>Phase I metabolism is mediated primarily by the CYP enzymes. These enzymes are present in several tissues throughout the body, including the intestine, lung, kidney, and adrenal glands, but are most highly concentrated in the liver. Numerous isoforms have been identified; the primary enzymes involved in drug metabolism are listed in Table 45.7. Considerable individuality is evident with respect to substrate specificity, polymorphic expression, and susceptibility to induction and inhibition.</p><small class=\"source\">PDF p. 782</small><p>The general pattern of development of CYP enzymes is illustrated in Fig. 45.2. In the fetal liver, studies have shown that CYP3A7 is by far the most significant CYP enzyme in terms of protein expression and activity. CYP3A7 concentrations decline during the neonatal period as CYP3A4 concentrations increase.23 CYP3A4 is the most abundant CYP enzyme in adults, accounting for 30% to 40% of hepatic CYP and as much as 70% of the content of CYP</p><small class=\"source\">PDF p. 782</small><p>in the intestine. Most other CYP enzymes develop rapidly in the neonatal period. Whether they are triggered by the loss of a maternal repressing factor or stimulated by transcription factors intrinsic to newborns, concentrations of CYP2D6 and CYP2E1 increase within hours of birth, followed closely by the CYP2C and CYP3A4 enzymes.22 By 1 month of age, hepatic concentrations are about 25% to 30% of those in adults. The notable exception is CYP1A2, which develops more slowly, reaching less than 5% of adult concentrations in the first month.22 It is generally assumed that premature babies exhibit greater impairment in drug metabolism than full-term infants; this response has been documented in several studies involving drugs metabolized by a wide range of CYP enzymes.26,27 It may result from the greater degree of immaturity of these enzymes at birth, a delay of the postnatal surge in CYP concentration observed in full-term babies, or a combination of these two factors.</p><small class=\"source\">PDF p. 782</small><p>The pharmacokinetics of many drugs in neonates is consistent with the pattern of development of the CYP enzymes shown in Fig. 45.2. Caffeine, which is administered for the treatment of neonatal apnea, exhibits an extremely prolonged half-life of several days in neonates compared with 4 to 6 hours in adults.26 This result is caused by the delayed development of the CYP1A2 enzyme, which is responsible for the demethylation of caffeine in the primary metabolic pathway. The structurally related bronchodilator theophylline also exhibits reduced clearance and a prolonged half-life in neonates. However, the effect is not as dramatic as that observed with caffeine because theophylline is partially oxidized by other CYP enzymes, such as CYP2E1, in addition to CYP1A2. For drugs metabolized primarily by CYP2D6 or CYP2C, it seems reasonable to expect drug clearance</p><small class=\"source\">PDF p. 782</small><figure class=\"source-page\"><a href=\"tables/ch045_page0782.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0782.jpg\" alt=\"Original source page 782, including its figures or tables\"></a><figcaption>Original source-page view · PDF 782. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"783\"><h2>PDF page 783 · Printed 776</h2><h3>Drug Metabolism In The Neonate</h3><p>to be low at birth but to increase rapidly during the first month of life. Recommended age-based dosing for phenytoin, which is a substrate for CYP2C9, supports this view. At birth, the phenytoin dose is 4 to 8 mg/kg every 24 hours, but therapeutic doses can be as high as 8 mg/kg every 8 hours after the first week of life as metabolism and clearance mature.</p><small class=\"source\">PDF p. 783</small><p>The clearance of drugs metabolized by CYP3A4 may be reduced less in neonates than substrates for other CYP enzymes if CYP3A7 is capable of contributing to the metabolic process. CYP3A4 and CYP3A7 show more than 85% amino acid sequence homology and have partially overlapping affinities for both endogenous and exogenous substrates.28 The catalytic activity of CYP3A4 toward drugs such as midazolam, carbamazepine, and nifedipine is greater than that of CYP3A7, whereas the latter appears relatively active in metabolizing erythromycin.28 However, even if catalytic activity is low, CYP3A7 may contribute to the overall clearance of a drug at birth, owing to the high concentrations present. This activity may account for the observation that the elimination of CYP3A substrates such as carbamazepine29 and the reverse transcriptase inhibitor nevirapine30 during the first week of life is relatively similar to that observed in adults.</p><small class=\"source\">PDF p. 783</small><p>The metabolism of phase II drugs is mediated by a number of different enzymes, the most important of which are N-acetyltransferase (acetylation), sulfotransferase (sulfation), and UGT (glucuronidation). Acetylation and glucuronidation are not completely developed at birth, whereas sulfation appears to be reasonably well developed relative to other pathways of drug metabolism. Glucuronidation is an important route of metabolism for many drugs (acetaminophen, morphine, zidovudine) as well as endogenous compounds such as bilirubin.23 Although UGT activity is generally presumed to be immature at birth, establishing a clear pattern for its development is complicated by the existence of numerous isoforms of the enzyme with broad and overlapping substrate specificity. UGT1A1, which is involved in the glucuronidation of bilirubin and raltegravir, is virtually absent in the fetus and develops slowly over several months after birth. Raltegravir, an antiretroviral often used to prevent transmission of human immunodeficiency virus (HIV) from mother to baby, exhibits reduced clearance in neonates and incomplete elimination in some.31 A somewhat similar pattern of development exists for UGT1A6, which is responsible for the glucuronidation of acetaminophen. UGT2B7 catalyzes the formation of morphine-3-glucuronide and morphine-6-glucuronide. Its activity is decreased in newborns and increases to adult levels by 2 to 6 months of age, thus morphine clearance in neonates remains well below that of older children.23 For some medications, such as acetaminophen, increased sulfation partially compensates for the reduced glucuronidation in neonates. The proportion of a dose of acetaminophen excreted as a sulfate conjugate is higher in neonates than in older children or adults. Similar to observations with drugs metabolized by CYP, glucuronidation in premature</p><small class=\"source\">PDF p. 783</small><p>infants is impaired to a greater extent than it is in full-term infants.32</p><small class=\"source\">PDF p. 783</small><p>Conclusions based on studies of drug metabolism in the term and preterm neonate must be interpreted with caution because of the small numbers of subjects in many investigations and the potentially confounding effects of genetics and disease states on metabolism. Nevertheless, the available data suggest the following tentative conclusions: 1. The rate of drug metabolism is generally low at birth in</p><small class=\"source\">PDF p. 783</small><p>full-term babies and even lower in premature infants, regardless of the specific route of metabolism. Decreased clearance and a prolonged drug half-life require drug administration with longer dosing intervals. 2. Many of the enzymes responsible for metabolism exhibit</p><small class=\"source\">PDF p. 783</small><p>significant development during the first month of life. Dosing regimens appropriate during the first few days of postnatal life may not be appropriate 3 to 4 weeks after birth because dose requirements may increase, and dosing intervals decrease. 3. The development of individual drug-metabolizing</p><small class=\"source\">PDF p. 783</small><p>enzymes varies widely among neonates and may be delayed in premature infants. Predicting clearance is difficult, and dosing regimens must be individualized for patients based on the careful observation of the patient’s response and tolerance; monitoring of plasma drug concentrations may be useful for selected drugs.</p><small class=\"source\">PDF p. 783</small><h3>Renal Excretion Of Drugs</h3><p>The kidneys are the most important organs for drug elimination for most agents. In the newborn, the most frequently used drugs, such as antimicrobial agents and caffeine in the premature neonate, are excreted by way of the kidney. Renal elimination of these drugs reflects and depends on neonatal renal function, which is characterized by a low GFR, low effective renal blood flow, and low tubular function (secretion and reabsorption) compared with that in the adult. The neonatal GFR is about 50% of the adult value and is greatly influenced by gestational age at birth. A term neonate has a GFR of 2 to 4 mL/min/1.73 m2, whereas the GFR at less than 34 weeks of gestation is about 0.7 to 0.8 mL/min/1.73 m2. The most rapid changes in renal function occur during the first week of life, but adult values are not reached until 6 to 12 months after birth in term neonates.23,24 As expected, it takes even longer for the GFR to reach adult values in preterm infants secondary to the smaller number of glomeruli present.24 Medications administered to the neonate can also cause a decrease in GFR and ultimately reduce the elimination of concurrent drugs. For example, indomethacin inhibits prostaglandin synthesis, which leads to an increase in renal vascular resistance and thus a reduction in renal blood flow. The consequence of this is a decreased clearance of other medications, such as gentamicin, that are dependent on glomerular filtration for elimination.</p><small class=\"source\">PDF p. 783</small><p>Effective renal blood flow may influence the rate at which drugs are presented to and eliminated by the kidneys. Available data suggest that there is low effective renal blood flow</p><small class=\"source\">PDF p. 783</small></section><section class=\"source-section\" data-pdf-page=\"784\"><h2>PDF page 784 · Printed 777</h2><h3>Renal Excretion Of Drugs</h3><p>during the first 2 days of life (34–99 mL/min/1.73 m2), which increases to 54 to 166 mL/min/1.73 m2 by 14 to 21 days and further increases to adult values of about 600 mL/min/1.73 m2 by age 1 to 2 years. These data are probably not applicable to premature infants with very low birth weight, particularly those who weigh less than 750 g at birth. It is assumed, pending definitive data, that the GFR and renal blood flow in these infants are substantially lower than those in bigger premature infants, such as those who weigh more than 1000 g at birth. Nevertheless, renal function in these patients is highly variable, as reflected in the highly variable body clearance of a number of commonly administered drugs.</p><small class=\"source\">PDF p. 784</small><p>Tubular secretion and reabsorption are also variable and immature in neonates, initially present at only 20% to 30% of the activity observed in adults.24 Tubular secretion approaches adult values by 7 to 12 months of age in term neonates, whereas reabsorption maturation is more gradual and continues through adolescence.23 In premature neonates, tubular function is even more limited. Drugs that require tubular secretion for elimination (e.g., furosemide, morphine) typically exhibit decreased clearance during the neonatal period.</p><small class=\"source\">PDF p. 784</small><p>The pharmacokinetic behavior of drugs eliminated through the neonatal kidneys exhibits characteristics similar to those underlying hepatic biotransformation. For instance, the half-lives of many antimicrobials, such as ampicillin (Fig. 45.3), show marked interindividual variability at birth, which narrows somewhat with advancing age. The plasma half-life also shortens progressively after birth, achieving adult rates of elimination within 1 month. Studies of the pharmacokinetics of ceftazidime, famotidine, and meropenem have shown direct correlations between plasma drug clearance and the maturational changes in renal function.17,24 The drug-dependent variability in the elimination process partially reflects the major renal mechanisms of drug excretion. Those drugs that undergo substantial elimination by glomerular filtration (e.g., aminoglycosides) may</p><small class=\"source\">PDF p. 784</small><p>be excreted more rapidly than those requiring substantial tubular excretion (e.g., penicillins).</p><small class=\"source\">PDF p. 784</small><p>As with hepatic metabolism, the renal excretion of certain drugs may be as efficient as that in adults. However, usually drug excretion by way of the neonatal kidneys is deficient relative to that in an adult. Pathophysiologic insults further compromise the inherent deficiency in drug elimination, complicating individual drug dosage regimens. Hypoxemia decreases the already slow glomerular and tubular functions in neonates, leading to the slower renal excretion of drugs, as shown with amikacin. Intrauterine growth restriction leads to a decrease in the number of nephrons and renal mass, leading to a prolonged half-life of drugs such as vancomycin.33 Moreover, very small infants, who receive the most drugs in the neonatal population, exhibit the worst functional deficiency in drug elimination.</p><small class=\"source\">PDF p. 784</small><p>Age-related (gestational and postnatal) changes have been considered in the dosage regimen recommendations for antibiotics and other drugs used in the treatment of infants. Drug doses, particularly for those agents excreted by the kidneys, are dynamically changing as functions of gestational and postnatal ages. For example, more than 70% of meropenem is excreted unchanged in the urine. It has a reported clearance of 0.253 to 0.389 L/h in preterm neonates compared with 0.414 to 0.753 L/h in term neonates, and the half-life of meropenem is 3.8 hours in preterm infants compared with 1 hour in adults.24 These differences have led to specific FDA-recommended dosing that varies with gestational and postnatal age. In general, the total daily dose of a drug is directly related to the postconceptional age, and the fetal maturity is inversely related to dose interval. Thus, as an infant matures, the total daily dose increases, and the dose interval decreases. However, the neonate is often unpredictable, and rigorous monitoring of drug efficacy and patient tolerability are required regardless of gestational and postnatal age.</p><small class=\"source\">PDF p. 784</small><figure class=\"source-page\"><a href=\"tables/ch045_page0784.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch045_page0784.jpg\" alt=\"Original source page 784, including its figures or tables\"></a><figcaption>Original source-page view · PDF 784. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"785\"><h2>PDF page 785 · Printed 778</h2><h3>Renal Excretion Of Drugs</h3><p>Key Points</p><small class=\"source\">PDF p. 785</small><h3>• Most Drugs Administered To The Mother Reach The Fetus;</h3><p>the extent of fetal exposure depends on maternal drug disposition and placental drug transfer.</p><small class=\"source\">PDF p. 785</small><h3>• Drug Absorption, Distribution, Metabolism, And Elimi-</h3><p>nation all fluctuate throughout pregnancy, impacting maternal serum concentrations of medications and ultimately fetal exposure.</p><small class=\"source\">PDF p. 785</small><h3>• The Primary Mode Of Drug Transfer Across The Placenta Is</h3><p>by simple, passive diffusion, which occurs most readily for a drug with high lipid solubility, low protein binding, low molecular weight, and in its unionized form.</p><small class=\"source\">PDF p. 785</small><h3>• Fewer Than 30 Drugs Are Positively Identified As Human</h3><p>teratogens, whereas the vast majority of medications approved by the FDA are categorized as undetermined teratogenic risk.</p><small class=\"source\">PDF p. 785</small><h3>References</h3><p>1. Koren G, et al. Treating the mother, protecting the unborn: the</p><small class=\"source\">PDF p. 785</small><p>motherisk approach. J Pediatr Pharmacol Ther. 2013;18:4. 2. Lynch M, et al. Improving safe use of medications during preg-</p><small class=\"source\">PDF p. 785</small><p>nancy: the role of patients, physicians, and pharmacists. Qual Health Res. 2017;0:1. 3. Isoherranen N, et al. Drug metabolism and transport during</p><small class=\"source\">PDF p. 785</small><p>pregnancy: how does drug disposition change during pregnancy and what are the mechanisms that cause such changes? Drug Metab Dispos. 2013;41:256. 4. Ke AB, et al. Pharmacometrics in pregnancy: an unmet need.</p><small class=\"source\">PDF p. 785</small><p>Annu Rev Pharmacol Toxicol. 2014;54:53–69. 5. Odutayo A, et al. Obstetric nephrology: renal hemodynamic</p><small class=\"source\">PDF p. 785</small><p>and metabolic physiology in normal pregnancy. Clin J Am Soc Nephrol. 2012;7:2073. 6. Tasnif Y, et al. Pregnancy-related pharmacokinetic changes. Clin</p><small class=\"source\">PDF p. 785</small><p>Pharmacol Ther. 2016;100:53. 7. Adam MP, et al. Evolving knowledge of the teratogenicity of</p><small class=\"source\">PDF p. 785</small><p>medications in human pregnancy. Am J Med Genet C Semin Med Genet. 2011;157c:175. 8. Lee N, et al. Organic cation transporter 3 facilitates fetal exposure to</p><small class=\"source\">PDF p. 785</small><p>metformin during pregnancy. Mol Pharmacol. 2018;94:1125–1131. 9. Han LW, et al. An update on expression and function of p-gp/</p><small class=\"source\">PDF p. 785</small><p>abcb1 and bcrp/abcg2 in the placenta and fetus. Expert Opin Drug Metab Toxicol. 2018;14:817–829. 10. Syme MR, et al. Drug transfer and metabolism by the human</p><small class=\"source\">PDF p. 785</small><p>placenta. Clin Pharmacokinet. 2004;43:487. 11. Ward RM, Varner MW. Principles of pharmacokinetics in the</p><small class=\"source\">PDF p. 785</small><p>pregnant woman and fetus. Clin Perinatol. 2019;46:383–398. 12. Blanford AT, et al. In vitro metabolism of prednisolone, dexa-</p><small class=\"source\">PDF p. 785</small><p>methasone, betamethasone, and cortisol by the human placenta. Am J Obstet Gynecol. 1977;127:264. 13. Abjuljalil K, et al. Fetal physiology based pharmacokinetic mod-</p><small class=\"source\">PDF p. 785</small><p>els: systems information on fetal blood cell components and binding proteins. Clin Pharmacokinet. 2020;59:629–642. 14. Blackburn ST. Pharmacology and pharmacokinetics during the</p><small class=\"source\">PDF p. 785</small><p>perinatal period. In: Gower LK, ed. Maternal, Fetal, and Neonatal Physiology: A Clinical Perspective. 4th ed. St. Louis: Elsevier; 2013:183. 15. De Sousa Mendes M, et al. A physiologically-based pharma-</p><small class=\"source\">PDF p. 785</small><p>cokinetic model to predict human fetal exposure for a drug</p><small class=\"source\">PDF p. 785</small><h3>• The Pharmacokinetic Processes Of Absorption, Distri-</h3><p>bution, metabolism, and elimination are immature in a neonate and develop at varying rates after birth. The immaturity is more pronounced and the development is slower in preterm neonates.</p><small class=\"source\">PDF p. 785</small><h3>• Neonates Often Have A Larger Vd But Delayed Excre-</h3><p>tion compared with older children or adults, resulting in the need for higher milligram-per-kilogram doses of medications with potentially longer dosing intervals.</p><small class=\"source\">PDF p. 785</small><h3>• Dosing Regimens For Neonates Over The First 3 To 4 Weeks</h3><p>of life are dynamic and require adjustment based on maturational changes in hepatic metabolism and renal elimination.</p><small class=\"source\">PDF p. 785</small><p>metabolized by several CYP450 pathways. Clin Pharmacokinet. 2017;56:537. 16. Robinson JF, et al. Differences in cytochrome P450 enzyme</p><small class=\"source\">PDF p. 785</small><p>expression and activity in fetal and adult tissues. Placenta. 2020;100:35–44. 17. Micromedex Solutions. Truven Health Analytics, Inc, Ann Arbor,</p><small class=\"source\">PDF p. 785</small><p>MI. Accessed October 28, 2017. http://www.micromedexsolutio ns.com 18. Nordeng H. Drug utilization in pregnant women. In: Drug Uti-</p><small class=\"source\">PDF p. 785</small><p>lization Research: Methods and Applications. Chichester, UK: John Wiley &amp; Sons Ltd; 2016:240. 19. Laffitte E, Revuz J. Thalidomide: an old drug with new clinical</p><small class=\"source\">PDF p. 785</small><p>applications. Expert Opin Drug Saf. 2004;3:47. 20. Tomson T, et al. Antiepileptic drug treatment in pregnancy:</p><small class=\"source\">PDF p. 785</small><p>changes in drug disposition and their clinical implications. Epilepsia. 2013;54:405. 21. American Epilepsy Society. The Use of Valproate by Women of</p><small class=\"source\">PDF p. 785</small><p>Childbearing Potential: Position Statement. June 8, 2021. Accessed February 28, 2022. https://www.aesnet.org/docs/default-source/ position-statements/2021-06-08-update-aes-vpa_position_ statement-final.pdf 22. Kearns GL, et al. Developmental pharmacology: drug disposi-</p><small class=\"source\">PDF p. 785</small><p>tion, action, and therapy in infants and children. N Engl J Med. 2003;349:1157. 23. Tayman C, et al. Neonatal pharmacology: extensive interindi-</p><small class=\"source\">PDF p. 785</small><p>vidual variability despite limited size. J Pediatr Pharmacol Ther. 2011;16:170. 24. Zimmerman KO, et al. Neonatal therapeutics: considerations for</p><small class=\"source\">PDF p. 785</small><p>dosing. Am J Perinatol. 2019;36:S18–S21. 25. Sampson MR, et al. Population pharmacokinetics of intrave-</p><small class=\"source\">PDF p. 785</small><p>nous acyclovir in preterm and term infants. Pediatr Infect Dis J. 2014;33:42–29. 26. Lee TC, et al. Population pharmacokinetics of intravenous caffeine in</p><small class=\"source\">PDF p. 785</small><p>neonates with apnea of prematurity. Clin Pharmacol Ther. 1997;61:628. 27. Pacifici GM. Clinical pharmacology of phenobarbital in neo-</p><small class=\"source\">PDF p. 785</small><p>nates: effects, metabolism and pharmacokinetics. Curr Pediatr Rev. 2016;12:48. 28. Ohmori S, et al. Differential catalytic properties in metabolism</p><small class=\"source\">PDF p. 785</small><p>of endogenous and exogenous substrates among CYP3A enzymes expressed in COS-7 cells. Biochem Biophys Acta. 1998;1380:297. 29. Singh B, et al. Treatment of neonatal seizures with carbamaze-</p><small class=\"source\">PDF p. 785</small><p>pine. J Child Neurol. 1996;11:378.</p><small class=\"source\">PDF p. 785</small></section><section class=\"source-section\" data-pdf-page=\"786\"><h2>PDF page 786 · Printed 779</h2><h3>• Dosing Regimens For Neonates Over The First 3 To 4 Weeks</h3><p>30. Musoke P, et al. A phase I/II study of the safety and pharma-</p><small class=\"source\">PDF p. 786</small><p>cokinetics of nevirapine in HIV-1-infected pregnant Ugandan women and their neonates (HIVNET 006). AIDS. 1999;13:479. 31. Clarke DF, et al. Impact of low birth weight and prematurity on</p><small class=\"source\">PDF p. 786</small><p>neonatal raltegravir pharmacokinetics: impact P1097. J Acquir Immune Defic Syndr. 2020;85:626–634.</p><small class=\"source\">PDF p. 786</small><p>32. O’Hara K, et al. Pharmacokinetics in neonatal prescribing;</p><small class=\"source\">PDF p. 786</small><p>evidence base, paradigm and the future. Br J Clin Pharmacol. 2015;80:1281. 33. Frattarelli DA, et al. Vancomycin elimination in human infants</p><small class=\"source\">PDF p. 786</small><p>with intrauterine growth retardation. Pediatr Infect Dis J. 2005;24:979.</p><small class=\"source\">PDF p. 786</small></section>", "guided": {"num": 45, "title": "Principles of Drug Use in the Fetus and Neonate", "hook": "Why can an adult therapeutic total drug concentration still be misleading in a newborn?", "audience": "Pediatric residents, neonatal fellows and clinicians studying the source edition", "prerequisites": "Core neonatal physiology and clinical assessment; foundational chapters support entry-level review.", "estimated_minutes": 25, "estimated_minutes_note": "Planning estimate for five units and feedback; full reference reading takes longer.", "lessons": [{"id": "L045-1", "objective_id": "O045-1", "objective": "Identify drug characteristics favoring passive transfer", "title": "Placental transfer", "level": "Essentials", "text": "Small, lipid-soluble, largely unionized and weakly protein-bound. These properties favor movement across placental membranes by passive diffusion.", "card_id": "fc-045-1", "question_id": "q-045-1", "pdf_page": 776, "printed_page": "769"}, {"id": "L045-2", "objective_id": "O045-2", "objective": "Predict a distribution difference for water-soluble drugs", "title": "Body water and distribution", "level": "Clinical Application", "text": "A larger volume of distribution per kilogram. Newborns have relatively more total and extracellular body water, increasing distribution of hydrophilic drugs.", "card_id": "fc-045-2", "question_id": "q-045-2", "pdf_page": 781, "printed_page": "774"}, {"id": "L045-3", "objective_id": "O045-3", "objective": "Interpret total concentrations in reduced protein binding", "title": "Free drug", "level": "Clinical Application", "text": "The unbound pharmacologically active fraction. Reduced binding increases the fraction available to exert pharmacologic effects; total adult ranges need cautious interpretation.", "card_id": "fc-045-3", "question_id": "q-045-3", "pdf_page": 781, "printed_page": "774"}, {"id": "L045-4", "objective_id": "O045-4", "objective": "Explain prolonged caffeine disposition", "title": "Enzyme maturation", "level": "Deep Dive", "text": "Delayed CYP1A2 activity. The primary caffeine demethylation pathway involves CYP1A2, which develops slowly after birth.", "card_id": "fc-045-4", "question_id": "q-045-4", "pdf_page": 782, "printed_page": "775"}, {"id": "L045-5", "objective_id": "O045-5", "objective": "Predict an interaction that reduces renal elimination", "title": "Renal drug interaction", "level": "Clinical Application", "text": "Reduced renal perfusion can decrease gentamicin clearance. Prostaglandin inhibition can increase renal vascular resistance and reduce clearance of filtration-dependent drugs.", "card_id": "fc-045-5", "question_id": "q-045-5", "pdf_page": 783, "printed_page": "776"}], "unavailable_levels": [], "review_status": "Model checked selected cited source passages; not specialist review", "case": null}});
